CREATE TABLE tb_impactos_seca (
    codigo BIGSERIAL PRIMARY KEY,
    municipio_codigo INTEGER not null,
    data_referencia DATE not null,
    data_insercao TIMESTAMP WITHOUT TIME ZONE,
    UNIQUE (municipio_codigo, data_referencia)
);

CREATE TABLE tb_registro_qualidade (
    codigo BIGSERIAL PRIMARY KEY,
    descricao VARCHAR(120) not null unique
);

CREATE TABLE tb_descricao_percepcao_seca (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_qnt_chuva (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_dt_chuva (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_de_chuva (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_sit_cultura (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_acesso_agua (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_restricoes_agua (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_descricao_cultura (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_registro (
    codigo BIGSERIAL PRIMARY KEY,
    impacto_codigo BIGSERIAL not null unique REFERENCES tb_impactos_seca (codigo),
    percepcao_seca SMALLINT REFERENCES tb_descricao_percepcao_seca (codigo),
    qnt_chuva SMALLINT REFERENCES tb_descricao_qnt_chuva (codigo),
    dt_chuva SMALLINT REFERENCES tb_descricao_dt_chuva (codigo),
    de_chuva SMALLINT REFERENCES tb_descricao_de_chuva (codigo),
    sit_cultura SMALLINT REFERENCES tb_descricao_sit_cultura (codigo),
    acesso_agua SMALLINT REFERENCES tb_descricao_acesso_agua (codigo),
    observacao TEXT,
    qualidade_dados SMALLINT not null,
    criado_em TIMESTAMP WITHOUT TIME ZONE not null
);

CREATE TABLE tb_registro_cultura (
    codigo BIGSERIAL PRIMARY KEY,
    registro_codigo BIGSERIAL not null REFERENCES tb_registro (codigo),
    cultura_codigo SMALLINT not null REFERENCES tb_descricao_cultura (codigo),
    UNIQUE (registro_codigo, cultura_codigo)
);

CREATE TABLE tb_registro_outras_culturas (
    codigo BIGSERIAL PRIMARY KEY,
    registro_codigo BIGSERIAL not null REFERENCES tb_registro (codigo),
    descricao TEXT not null
);

CREATE TABLE tb_descricao_impactos_agropecuaria (
    codigo SMALLINT PRIMARY KEY,
    codigo_alpha VARCHAR(120) not null,
    descricao TEXT not null,
    UNIQUE (codigo_alpha, descricao)
);

CREATE TABLE tb_registro_impacto_atividade (
    codigo BIGSERIAL PRIMARY KEY,
    registro_codigo BIGSERIAL not null REFERENCES tb_registro (codigo),
    impacto_codigo SMALLINT not null REFERENCES tb_descricao_impactos_agropecuaria (codigo),
    UNIQUE (registro_codigo, impacto_codigo)
);

CREATE TABLE tb_registro_restricao_agua (
    codigo BIGSERIAL PRIMARY KEY,
    registro_codigo BIGSERIAL not null REFERENCES tb_registro (codigo),
    restricao_codigo SMALLINT not null REFERENCES tb_descricao_restricoes_agua (codigo),
    UNIQUE (registro_codigo, restricao_codigo)
);
